import java.io.*;
import java.util.*;

public class Main {
    static final int INF = 1000000001;

    static class Pair {
        int first, second;
        Pair(int first, int second) {
            this.first = first;
            this.second = second;
        }
    }

    static int[] sort(int[] arr) {
        if (arr.length < 2) {
            return arr;
        }
        int left = 0;
        int right = arr.length - 1;
        int pivot = arr.length / 2;

        int temp = arr[pivot];
        arr[pivot] = arr[right];
        arr[right] = temp;

        for (int i = 0; i < arr.length; i++) {
            if (arr[i] < arr[right]) {
                temp = arr[i];
                arr[i] = arr[left];
                arr[left] = temp;
                left++;
            }
        }

        temp = arr[left];
        arr[left] = arr[right];
        arr[right] = temp;

